const grpc = require('@grpc/grpc-js');
const { db } = require('../db');
const { authenticateUser } = require('../auth');

async function revokeClientApiKey(call, callback) {
  const user = await authenticateUser(call.metadata);
  if (!user) return callback({ code: grpc.status.UNAUTHENTICATED });

  const { keyId } = call.request;
  const result = await db.query(
    'UPDATE api_tokens SET status = $1, revoked_at = NOW() WHERE id = $2 AND owner_id = $3 RETURNING id',
    ['REVOKED', keyId, user.id]
  );

  if (result.rowCount === 0) return callback({ code: grpc.status.PERMISSION_DENIED, message: 'Key not found or unauthorized' });
  return callback(null, { revokedKeyId: result.rows[0].id });
}
